import re,pathlib,yaml,collections,sys
d=pathlib.Path("30_Library/100_zettelkasten")
names={p.stem:p for p in d.parent.rglob("*.md")}
def load(p):
    t=p.read_text(errors="ignore"); m=re.match(r"^---\n(.*?)\n---\n?(.*)$",t,re.S)
    try: fm=yaml.safe_load(m.group(1)) or {} if m else {}
    except Exception: fm={"_bad":1}
    return fm,(m.group(2) if m else t)
def links(t): return [x.split("|")[0].split("#")[0].strip() for x in re.findall(r"\[\[([^\]]+?)\]\]",t)]
moc=names["MOC - Character and Virtue"].read_text()
sec={}
cluster=[]
for part in moc.split("\n## 2. ")[1].split("\n## 3.")[0:1]: cluster+=links(part)
sec5=moc.split("\n## 5. ")[1].split("\n## 6.")[0]; kids=links(sec5)
core=[]
for n in cluster+kids:
    if n in names and n not in core: core.append(n)
# one hop: strength-like notes linked from core
extra=[]
for n in core:
    for l in links(load(names[n])[1]):
        if l in names and l not in core and l not in extra and re.match(r"^(\w[\w\- ]*) is |^VIA |Skills \(",l): extra.append(l)
core+=extra
back=collections.defaultdict(set)
for p in d.glob("*.md"):
    for l in set(links(p.read_text(errors="ignore"))): back[l].add(p.stem)
for n in core:
    fm,b=load(names[n])
    own=fm.get("own_words")
    print(f"\n#### {n}\n type={fm.get('type')} status={fm.get('status')} conf={fm.get('conformant')} epi={fm.get('epistemic_status')} own={own} in={len(back[n])} words={len(b.split())} keys={[k for k in fm if k.startswith('prodos') or k in('axiom','updated','uid','last_reviewed','confidence','definition','proposition')]}")
    if len(sys.argv)>1: print(b.strip()[:int(sys.argv[1])])
print("\nCOUNT",len(core)); print("ALL MOC links",len(set(links(moc))), "missing:",[l for l in set(links(moc)) if l not in names])
pathlib.Path(sys.argv[0]).with_name("core.txt").write_text("\n".join(core))
E
uv run -q --with pyyaml python3 $S/graph.py; git status --short | grep -F -f $S/core.txt

