S=pathlib.Path(__file__).parent; ch=json.loads((S/"changed.json").read_text())
base={p.stem:p for p in pathlib.Path("30_Library").rglob("*.md")}
lost=0;bad=0
for b in (S/"before").glob("*.md"):
    a=base[b.stem].read_text(); o=b.read_text()
    L=lambda t:{x.split("|")[0].split("#")[0] for x in re.findall(r"\[\[([^\]]+?)\]\]",t)}
