        gone=[l for l in o[m.start():].split("\n") if l.strip() and not l.startswith("#") and l not in a]
        if gone: print("CHANGED-LINES",b.stem,len(gone),gone[0][:120])
for n in ch:
    t=base[n].read_text()
    try: yaml.safe_load(re.match(r"^---\n(.*?)\n---\n",t,re.S).group(1))
    except Exception as e: bad+=1; print("YAML",n,e)
    for x in re.findall(r"\[\[([^\]]+?)\]\]",t):
        k=x.split("|")[0].split("#")[0].split("/")[-1].strip()
        if k and k not in base and not x.startswith("BookFusion"): print("DANGLING",n,k)
print("lost",lost,"yaml-bad",bad,"checked",len(ch))
(S/"paths.txt").write_text("\n".join(str(base[n]) for n in ch))
E
